"""解析测试台标准输出中的单行结果。

支持三类记录（均为单行，名称去除首尾空白后必须非空）：

- ``ASSERT PASS name``
- ``ASSERT FAIL name message``（message 可含空白，可为空）
- ``COVER name``

断言状态取最后一次结果；失败次数按 FAIL 记录累加；
覆盖率点按命中次数累加。所有映射均按名称首次出现的顺序保存。
"""

#: 三类记录的标记前缀。
ASSERT_PREFIX = "ASSERT PASS "
ASSERT_FAIL_PREFIX = "ASSERT FAIL "
COVER_PREFIX = "COVER "


class ResultCollector:
    """按行收集断言与覆盖率结果。"""

    def __init__(self):
        #: name -> {"status": "passed"/"failed", "fail_count": int}
        self.assertions = {}
        #: name -> 命中次数
        self.coverage = {}

    def feed_line(self, line):
        """处理一行（不含行尾换行）。无法识别的行将被忽略。

        :returns: 识别出的记录类型描述（仅供调试），未识别返回 None。
        """
        if line.startswith(ASSERT_FAIL_PREFIX):
            rest = line[len(ASSERT_FAIL_PREFIX):]
            parts = rest.split(None, 1)
            if not parts:
                return None
            name = parts[0].strip()
            if not name:
                return None
            message = parts[1].strip() if len(parts) > 1 else ""
            entry = self.assertions.setdefault(
                name, {"status": "failed", "fail_count": 0}
            )
            entry["status"] = "failed"
            entry["fail_count"] += 1
            return ("assert_fail", name, message)

        if line.startswith(ASSERT_PREFIX):
            name = line[len(ASSERT_PREFIX):].strip()
            if not name:
                return None
            entry = self.assertions.setdefault(
                name, {"status": "passed", "fail_count": 0}
            )
            entry["status"] = "passed"
            return ("assert_pass", name)

        if line.startswith(COVER_PREFIX):
            name = line[len(COVER_PREFIX):].strip()
            if not name:
                return None
            self.coverage[name] = self.coverage.get(name, 0) + 1
            return ("cover", name)

        return None

    def feed_text(self, text):
        """处理整段文本，按 \\n / \\r\\n 分行。"""
        for raw in text.splitlines():
            self.feed_line(raw)

    @property
    def has_failure(self):
        """是否出现过且最终仍处于失败状态的断言。"""
        return any(a["status"] == "failed" for a in self.assertions.values())

